import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/index.md","filePath":"api-reference/index.md"}'),o={name:"api-reference/index.md"};function c(i,e,n,s,h,l){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>Every method of skapi-py 2.4.0. Each one raises <a href="/introduction/errors.html"><code>SkapiError</code></a> on failure.</p><h2 id="connection" tabindex="-1"><a href="/api-reference/connection.html">Connection</a> <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;[Connection](/api-reference/connection)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/connection.html#skapi"><code>Skapi(project_id, *, storage=None, timeout=120, encryption=None)</code></a></td><td>connects to one project</td></tr><tr><td><a href="/api-reference/connection.html#get-connection-info"><code>get_connection_info(refresh=False)</code></a></td><td>project name and settings</td></tr></tbody></table><h2 id="authentication" tabindex="-1"><a href="/api-reference/authentication.html">Authentication</a> <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;[Authentication](/api-reference/authentication)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/authentication.html#signup"><code>signup(params, option=None)</code></a></td><td>creates an account</td></tr><tr><td><a href="/api-reference/authentication.html#resend-signup-confirmation"><code>resend_signup_confirmation()</code></a></td><td>sends the confirmation e-mail again</td></tr><tr><td><a href="/api-reference/authentication.html#login"><code>login(email, password, username=None)</code></a></td><td>signs in</td></tr><tr><td><a href="/api-reference/authentication.html#verify-mfa"><code>verify_mfa(code)</code></a></td><td>finishes a login that needs an authenticator code</td></tr><tr><td><a href="/api-reference/authentication.html#logout"><code>logout(global_logout=False)</code></a></td><td>signs out</td></tr><tr><td><a href="/api-reference/authentication.html#get-profile"><code>get_profile(refresh_token=False)</code></a></td><td>the signed-in user&#39;s profile</td></tr><tr><td><a href="/api-reference/authentication.html#login-with-token"><code>login_with_token(id_token, access_token, refresh_token)</code></a></td><td>adopts tokens from another sign-in</td></tr><tr><td><a href="/api-reference/authentication.html#update-profile"><code>update_profile(params)</code></a></td><td>changes the user&#39;s profile</td></tr><tr><td><a href="/api-reference/authentication.html#change-password"><code>change_password(current_password, new_password)</code></a></td><td>changes the password</td></tr><tr><td><a href="/api-reference/authentication.html#forgot-password"><code>forgot_password(email)</code></a></td><td>sends a password reset code</td></tr><tr><td><a href="/api-reference/authentication.html#reset-password"><code>reset_password(email, code, new_password)</code></a></td><td>sets a new password with the code</td></tr><tr><td><a href="/api-reference/authentication.html#verify-email"><code>verify_email(code=None)</code></a></td><td>sends or checks an e-mail verification code</td></tr><tr><td><a href="/api-reference/authentication.html#last-verified-email"><code>last_verified_email(revert=None)</code></a></td><td>the last verified e-mail</td></tr><tr><td><a href="/api-reference/authentication.html#disable-account"><code>disable_account()</code></a></td><td>disables the user&#39;s own account</td></tr><tr><td><a href="/api-reference/authentication.html#recover-account"><code>recover_account(redirect=False)</code></a></td><td>sends the recovery e-mail to a disabled account</td></tr><tr><td><a href="/api-reference/authentication.html#open-id-login"><code>open_id_login(token, id)</code></a></td><td>signs in through an OpenID provider</td></tr><tr><td><a href="/api-reference/authentication.html#anonymous-login"><code>anonymous_login()</code></a></td><td>a temporary account without e-mail or password</td></tr><tr><td><a href="/api-reference/authentication.html#verify-anonymous-session"><code>verify_anonymous_session()</code></a></td><td>checks a restored temporary account still exists</td></tr><tr><td><a href="/api-reference/authentication.html#setup-mfa"><code>setup_mfa()</code></a> / <a href="/api-reference/authentication.html#enable-mfa"><code>enable_mfa(code)</code></a> / <a href="/api-reference/authentication.html#disable-mfa"><code>disable_mfa()</code></a> / <a href="/api-reference/authentication.html#get-mfa-status"><code>get_mfa_status()</code></a></td><td>two-step login with an authenticator app</td></tr></tbody></table><h2 id="database" tabindex="-1"><a href="/api-reference/database.html">Database</a> <a class="header-anchor" href="#database" aria-label="Permalink to &quot;[Database](/api-reference/database)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/database.html#post-record"><code>post_record(data, config, files=None)</code></a></td><td>creates or updates a record</td></tr><tr><td><a href="/api-reference/database.html#post-records"><code>post_records(items)</code></a></td><td>many records in few requests</td></tr><tr><td><a href="/api-reference/database.html#get-records"><code>get_records(query, fetch_options=None)</code></a></td><td>reads records</td></tr><tr><td><a href="/api-reference/database.html#delete-records"><code>delete_records(query)</code></a></td><td>deletes records</td></tr><tr><td><a href="/api-reference/database.html#get-tables"><code>get_tables</code></a> / <a href="/api-reference/database.html#get-tags"><code>get_tags</code></a> / <a href="/api-reference/database.html#get-indexes"><code>get_indexes</code></a> / <a href="/api-reference/database.html#get-unique-id"><code>get_unique_id</code></a></td><td>what the database holds</td></tr><tr><td><a href="/api-reference/database.html#upload-files"><code>upload_files(files, record_id)</code></a></td><td>attaches files to a record</td></tr><tr><td><a href="/api-reference/database.html#get-file"><code>get_file(url, config=None)</code></a></td><td>downloads a file, or makes a link to it</td></tr><tr><td><a href="/api-reference/database.html#delete-files"><code>delete_files(endpoints)</code></a></td><td>removes files from records</td></tr><tr><td><a href="/api-reference/database.html#grant-private-record-access"><code>grant_private_record_access</code></a> / <a href="/api-reference/database.html#remove-private-record-access"><code>remove_private_record_access</code></a> / <a href="/api-reference/database.html#list-private-record-access"><code>list_private_record_access</code></a> / <a href="/api-reference/database.html#request-private-record-access-key"><code>request_private_record_access_key</code></a></td><td>sharing private records</td></tr></tbody></table><h2 id="encryption" tabindex="-1"><a href="/api-reference/encryption.html">Encryption</a> <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;[Encryption](/api-reference/encryption)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/encryption.html#get-encryption-status"><code>get_encryption_status()</code></a></td><td>locked, unlocked or disabled</td></tr><tr><td><a href="/api-reference/encryption.html#unlock-encryption"><code>unlock_encryption(password)</code></a> / <a href="/api-reference/encryption.html#lock-encryption"><code>lock_encryption()</code></a></td><td>opens or forgets the user&#39;s keys</td></tr><tr><td><a href="/api-reference/encryption.html#unlock-encryption-with-recovery-code"><code>unlock_encryption_with_recovery_code(code, password=None)</code></a> / <a href="/api-reference/encryption.html#regenerate-encryption-recovery-code"><code>regenerate_encryption_recovery_code()</code></a></td><td>encryption recovery codes (the first one is shown once in <code>get_connection_info()</code>)</td></tr><tr><td><a href="/api-reference/encryption.html#pin-peer-key"><code>pin_peer_key(user_id, fingerprint)</code></a></td><td>trusts another user&#39;s key for sharing</td></tr><tr><td><a href="/api-reference/encryption.html#is-withheld"><code>is_withheld(value)</code></a></td><td>tells the placeholder of undecryptable data apart</td></tr></tbody></table><h2 id="users" tabindex="-1"><a href="/api-reference/users.html">Users</a> <a class="header-anchor" href="#users" aria-label="Permalink to &quot;[Users](/api-reference/users)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/users.html#get-users"><code>get_users(params=None, fetch_options=None)</code></a></td><td>searches the project&#39;s users</td></tr><tr><td><a href="/api-reference/users.html#subscribe"><code>subscribe(params)</code></a> / <a href="/api-reference/users.html#unsubscribe"><code>unsubscribe(params)</code></a></td><td>subscribes to another user</td></tr><tr><td><a href="/api-reference/users.html#block-subscriber"><code>block_subscriber(params)</code></a> / <a href="/api-reference/users.html#unblock-subscriber"><code>unblock_subscriber(params)</code></a></td><td>blocks a subscriber</td></tr><tr><td><a href="/api-reference/users.html#get-subscriptions"><code>get_subscriptions(params)</code></a></td><td>who subscribes to whom</td></tr><tr><td><a href="/api-reference/users.html#get-feed"><code>get_feed(params=None)</code></a></td><td>records from the users you subscribe to</td></tr><tr><td><a href="/api-reference/users.html#subscribe-newsletter"><code>subscribe_newsletter(params)</code></a> / <a href="/api-reference/users.html#unsubscribe-newsletter"><code>unsubscribe_newsletter(group)</code></a></td><td>newsletter subscription</td></tr><tr><td><a href="/api-reference/users.html#get-newsletters"><code>get_newsletters(params=None)</code></a> / <a href="/api-reference/users.html#get-newsletter-subscription"><code>get_newsletter_subscription()</code></a></td><td>sent newsletters and the user&#39;s subscriptions</td></tr><tr><td><a href="/api-reference/users.html#send-inquiry"><code>send_inquiry(data)</code></a></td><td>sends a message to the project owner</td></tr></tbody></table><h2 id="realtime" tabindex="-1"><a href="/api-reference/realtime.html">Realtime</a> <a class="header-anchor" href="#realtime" aria-label="Permalink to &quot;[Realtime](/api-reference/realtime)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/realtime.html#connect-realtime"><code>connect_realtime(callback)</code></a> / <a href="/api-reference/realtime.html#close-realtime"><code>close_realtime()</code></a></td><td>opens or closes the realtime connection</td></tr><tr><td><a href="/api-reference/realtime.html#join-realtime"><code>join_realtime(group)</code></a></td><td>joins or leaves a group</td></tr><tr><td><a href="/api-reference/realtime.html#post-realtime"><code>post_realtime(message, recipient, notification=None)</code></a></td><td>sends to a user or to the group</td></tr><tr><td><a href="/api-reference/realtime.html#get-realtime-groups"><code>get_realtime_groups(params=None)</code></a> / <a href="/api-reference/realtime.html#get-realtime-users"><code>get_realtime_users(params=None)</code></a></td><td>who is connected where</td></tr></tbody></table><h2 id="api-bridge" tabindex="-1"><a href="/api-reference/api-bridge.html">API Bridge</a> <a class="header-anchor" href="#api-bridge" aria-label="Permalink to &quot;[API Bridge](/api-reference/api-bridge)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/api-bridge.html#forward-request"><code>forward_request(options, form=None, on_stream=None)</code></a></td><td>calls another API through Skapi, with your client secrets</td></tr><tr><td><a href="/api-reference/api-bridge.html#forward-request-poll"><code>forward_request_poll(request_id)</code></a> / <a href="/api-reference/api-bridge.html#forward-request-stream"><code>forward_request_stream(request_id)</code></a></td><td>waits for a queued or streamed answer</td></tr><tr><td><a href="/api-reference/api-bridge.html#forward-request-finalize"><code>forward_request_finalize(request_id, data)</code></a></td><td>stores a streamed request&#39;s final answer</td></tr><tr><td><a href="/api-reference/api-bridge.html#forward-request-history"><code>forward_request_history(params)</code></a></td><td>past forwarded requests and their answers</td></tr><tr><td><a href="/api-reference/api-bridge.html#cancel-forward-request"><code>cancel_forward_request(params)</code></a> / <a href="/api-reference/api-bridge.html#forward-request-queue-count"><code>forward_request_queue_count(params)</code></a></td><td>queue control</td></tr></tbody></table><h2 id="tickets" tabindex="-1"><a href="/api-reference/tickets.html">Tickets</a> <a class="header-anchor" href="#tickets" aria-label="Permalink to &quot;[Tickets](/api-reference/tickets)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/tickets.html#consume-ticket"><code>consume_ticket(ticket_id, method, data, auth)</code></a></td><td>calls a ticket</td></tr><tr><td><a href="/api-reference/tickets.html#get-tickets"><code>get_tickets(params=None)</code></a></td><td>the project&#39;s tickets</td></tr><tr><td><a href="/api-reference/tickets.html#get-consumed-tickets"><code>get_consumed_tickets(params=None)</code></a></td><td>the user&#39;s own ticket calls</td></tr></tbody></table>',18)])])}cons